2	
3	import (
4		"context"
5		"fmt"
6	
7		"github.com/aws/aws-sdk-go-v2/aws"
8		"github.com/aws/aws-sdk-go-v2/service/acmpca"
9		"github.com/aws/aws-sdk-go-v2/service/acmpca/types"
10		"github.com/gruntwork-io/cloud-nuke/config"
11		"github.com/gruntwork-io/cloud-nuke/logging"
12		"github.com/gruntwork-io/cloud-nuke/resource"
13	)
14	
15	const (
16		// permanentDeletionDays is the number of days before a CA is permanently deleted.
17		// AWS allows 7-30 days; we use the minimum since cloud-nuke targets non-production resources.
18		permanentDeletionDays = 7
19	)
20	
21	// ACMPCAAPI defines the interface for ACM PCA operations.
22	type ACMPCAAPI interface {
23		DeleteCertificateAuthority(ctx context.Context, params *acmpca.DeleteCertificateAuthorityInput, optFns ...func(*acmpca.Options)) (*acmpca.DeleteCertificateAuthorityOutput, error)
24		DescribeCertificateAuthority(ctx context.Context, params *acmpca.DescribeCertificateAuthorityInput, optFns ...func(*acmpca.Options)) (*acmpca.DescribeCertificateAuthorityOutput, error)
25		ListCertificateAuthorities(ctx context.Context, params *acmpca.ListCertificateAuthoritiesInput, optFns ...func(*acmpca.Options)) (*acmpca.ListCertificateAuthoritiesOutput, error)
26		UpdateCertificateAuthority(ctx context.Context, params *acmpca.UpdateCertificateAuthorityInput, optFns ...func(*acmpca.Options)) (*acmpca.UpdateCertificateAuthorityOutput, error)
27	}
28	
29	// NewACMPCA creates a new ACMPCA resource using the generic resource pattern.
30	func NewACMPCA() AwsResource {
31		return NewAwsResource(&resource.Resource[ACMPCAAPI]{
32			ResourceTypeName: "acmpca",
33			BatchSize:        10,
34			InitClient: WrapAwsInitClient(func(r *resource.Resource[ACMPCAAPI], cfg aws.Config) {
35				r.Scope.Region = cfg.Region
36				r.Client = acmpca.NewFromConfig(cfg)
37			}),
38			ConfigGetter: func(c config.Config) config.ResourceType {
39				return c.ACMPCA
40			},
41			Lister: listACMPCA,
42			Nuker:  resource.SimpleBatchDeleter(deleteACMPCA),
43		})
44	}
45	
46	// listACMPCA retrieves all ACM PCA certificate authorities that match the config filters.
47	func listACMPCA(ctx context.Context, client ACMPCAAPI, scope resource.Scope, cfg config.ResourceType) ([]*string, error) {
48		var arns []*string
49	
50		paginator := acmpca.NewListCertificateAuthoritiesPaginator(client, &acmpca.ListCertificateAuthoritiesInput{})
51		for paginator.HasMorePages() {
52			page, err := paginator.NextPage(ctx)
53			if err != nil {
54				return nil, err
55			}
56	
57			for _, ca := range page.CertificateAuthorities {
58				if shouldIncludeACMPCA(ca, cfg) {
59					arns = append(arns, ca.Arn)
60				}
61			}
62		}
63	
64		return arns, nil
65	}
66	
67	// shouldIncludeACMPCA determines if an ACM PCA should be included based on config filters.
68	func shouldIncludeACMPCA(ca types.CertificateAuthority, cfg config.ResourceType) bool {
69		if ca.Status == types.CertificateAuthorityStatusDeleted {
70			return false
71		}
72	
73		// Use LastStateChangeAt as the reference time for time-based filters.
74		// Fall back to CreatedAt if the CA state was never changed.
75		referenceTime := aws.ToTime(ca.LastStateChangeAt)
76		if ca.LastStateChangeAt == nil {
77			referenceTime = aws.ToTime(ca.CreatedAt)
78		}
79	
80		return cfg.ShouldInclude(config.ResourceValue{Time: &referenceTime})
81	}
82	
83	// deleteACMPCA deletes a single ACM PCA certificate authority.
84	// This function handles the multi-step deletion process:
85	// 1. Describe the CA to get its current status
86	// 2. Disable the CA if it's in ACTIVE state (AWS requires this before deletion)
87	// 3. Delete the CA with a 7-day restoration period
88	func deleteACMPCA(ctx context.Context, client ACMPCAAPI, arn *string) error {
89		arnStr := aws.ToString(arn)
90	
91		logging.Debugf("Fetching CA details for ACMPCA %s", arnStr)
92		details, err := client.DescribeCertificateAuthority(ctx, &acmpca.DescribeCertificateAuthorityInput{
93			CertificateAuthorityArn: arn,
94		})
95		if err != nil {
96			return fmt.Errorf("failed to describe ACMPCA %s: %w", arnStr, err)
97		}
98		if details.CertificateAuthority == nil {
99			return fmt.Errorf("CA not found: %s", arnStr)
100		}
101		if details.CertificateAuthority.Status == "" {
102			return fmt.Errorf("CA status unavailable: %s", arnStr)
103		}
104	
105		// AWS requires ACTIVE CAs to be disabled before deletion.
106		// CAs in CREATING, PENDING_CERTIFICATE, DISABLED, or DELETED states can be deleted directly.
107		if needsDisableBeforeDelete(details.CertificateAuthority.Status) {
108			logging.Debugf("Disabling ACMPCA %s before deletion", arnStr)
109			if _, err = client.UpdateCertificateAuthority(ctx, &acmpca.UpdateCertificateAuthorityInput{
110				CertificateAuthorityArn: arn,
111				Status:                  types.CertificateAuthorityStatusDisabled,
112			}); err != nil {
113				return fmt.Errorf("failed to disable ACMPCA %s: %w", arnStr, err)
114			}
115		}
116	
117		_, err = client.DeleteCertificateAuthority(ctx, &acmpca.DeleteCertificateAuthorityInput{
118			CertificateAuthorityArn:     arn,
119			PermanentDeletionTimeInDays: aws.Int32(permanentDeletionDays),
120		})
121		if err != nil {
122			return fmt.Errorf("failed to delete ACMPCA %s: %w", arnStr, err)
123		}
124	
125		logging.Debugf("Deleted ACMPCA: %s", arnStr)
126		return nil
127	}
128	
129	// needsDisableBeforeDelete returns true if the CA must be disabled before deletion.
130	func needsDisableBeforeDelete(status types.CertificateAuthorityStatus) bool {
131		switch status {
132		case types.CertificateAuthorityStatusCreating,
133			types.CertificateAuthorityStatusPendingCertificate,
134			types.CertificateAuthorityStatusDisabled,
135			types.CertificateAuthorityStatusDeleted:
136			return false
137		default:
138			// ACTIVE, EXPIRED, FAILED states require disable first
139			return true
140		}
141	}
