40	func listCloudMapNamespaces(ctx context.Context, client CloudMapNamespacesAPI, scope resource.Scope, cfg config.ResourceType) ([]*string, error) {
41		var namespaceIds []*string
42	
43		paginator := servicediscovery.NewListNamespacesPaginator(client, &servicediscovery.ListNamespacesInput{})
44		for paginator.HasMorePages() {
45			page, err := paginator.NextPage(ctx)
