71	func deleteCloudMapNamespace(ctx context.Context, client CloudMapNamespacesAPI, id *string) error {
72		// Log Route53 hosted zone info if present (will be auto-cleaned by AWS)
73		if err := logHostedZoneInfo(ctx, client, id); err != nil {
74			logging.Debugf("Error getting namespace %s: %s", aws.ToString(id), err)
75		}
76	
77		_, err := client.DeleteNamespace(ctx, &servicediscovery.DeleteNamespaceInput{Id: id})
78		return err
79	}
