81	// logHostedZoneInfo logs information about Route53 hosted zones that will be auto-cleaned.
82	func logHostedZoneInfo(ctx context.Context, client CloudMapNamespacesAPI, id *string) error {
83		resp, err := client.GetNamespace(ctx, &servicediscovery.GetNamespaceInput{Id: id})
84		if err != nil {
85			return err
86		}
87	
88		if resp.Namespace.Properties != nil &&
89			resp.Namespace.Properties.DnsProperties != nil &&
90			resp.Namespace.Properties.DnsProperties.HostedZoneId != nil {
91			logging.Debugf("Namespace %s has associated Route53 hosted zone %s - it will be cleaned automatically",
92				aws.ToString(id), aws.ToString(resp.Namespace.Properties.DnsProperties.HostedZoneId))
93		}
94	
95		return nil
96	}
