98	// getNamespaceTags retrieves all tags for a Cloud Map namespace.
99	func getNamespaceTags(ctx context.Context, client CloudMapNamespacesAPI, arn *string) (map[string]string, error) {
100		resp, err := client.ListTagsForResource(ctx, &servicediscovery.ListTagsForResourceInput{
101			ResourceARN: arn,
102		})
103		if err != nil {
104			logging.Debugf("Error getting tags for Cloud Map namespace with ARN %s", aws.ToString(arn))
105			return nil, errors.WithStackTrace(err)
106		}
107	
108		tags := make(map[string]string)
109		for _, tag := range resp.Tags {
110			if tag.Key != nil && tag.Value != nil {
111				tags[aws.ToString(tag.Key)] = aws.ToString(tag.Value)
112			}
113		}
114	
115		return tags, nil
116	}
